// ListsVisible says "{count, number} visible"
// in the language the app shows under cx.
func ListsVisible(cx *core.Scope, count int) string { return For(cx).ListsVisible(count) }

// ListsVisible says "{count, number} visible"
// in the language of msgs.
func (msgs Messages) ListsVisible(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ListsVisible; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return i18n.FormatNumber("en", float64(count)) + " visible"
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " ظاهر"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 项可见"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 項可見"
		}
	}
}

// ListsItemsColumns says "{items, plural, one {# item} other {# items}}, {columns, plural, one {# column} other {# columns}}"
// in the language the app shows under cx.
func ListsItemsColumns(cx *core.Scope, items int, columns int) string {
	return For(cx).ListsItemsColumns(items, columns)
}

// ListsItemsColumns says "{items, plural, one {# item} other {# items}}, {columns, plural, one {# column} other {# columns}}"
// in the language of msgs.
func (msgs Messages) ListsItemsColumns(items int, columns int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ListsItemsColumns; f != nil {
			return f(items, columns)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(items)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(items)))
				b.WriteString(" item")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(items)))
				b.WriteString(" items")
			}
			b.WriteString(", ")
			switch i18n.Cardinal("en", float64(columns)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(columns)))
				b.WriteString(" column")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(columns)))
				b.WriteString(" columns")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(items)) + " عنصر، " + i18n.FormatNumber("ar", float64(columns)) + " أعمدة"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(items)) + " 项，" + i18n.FormatNumber("zh-Hans", float64(columns)) + " 列"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(items)) + " 項，" + i18n.FormatNumber("zh-Hant", float64(columns)) + " 列"
		}
	}
}

