func (msgs Messages) CanvasVsAverage(delta string) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].CanvasVsAverage; f != nil {
			return f(delta)
		}
		switch lang {
		case "", "en":
			return delta + " vs. average"
		case "ar":
			return delta + " مقابل المتوسط"
		case "zh-Hans":
			return "较平均 " + delta
		case "zh-Hant":
			return "較平均 " + delta
		}
	}
}

// CanvasStrokesPoints says "{strokes, number} · {points, plural, one {# point} other {# points}}"
// in the language the app shows under cx.
func CanvasStrokesPoints(cx *core.Scope, strokes int, points int) string {
	return For(cx).CanvasStrokesPoints(strokes, points)
}

// CanvasStrokesPoints says "{strokes, number} · {points, plural, one {# point} other {# points}}"
// in the language of msgs.
func (msgs Messages) CanvasStrokesPoints(strokes int, points int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].CanvasStrokesPoints; f != nil {
			return f(strokes, points)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString(i18n.FormatNumber("en", float64(strokes)))
			b.WriteString(" · ")
			switch i18n.Cardinal("en", float64(points)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(points)))
				b.WriteString(" point")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(points)))
				b.WriteString(" points")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(strokes)) + " · " + i18n.FormatNumber("ar", float64(points)) + " نقطة"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(strokes)) + " · " + i18n.FormatNumber("zh-Hans", float64(points)) + " 个点"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(strokes)) + " · " + i18n.FormatNumber("zh-Hant", float64(points)) + " 個點"
		}
	}
}

