// CompCharacters says "{count, plural, one {# character} other {# characters}}"
// in the language the app shows under cx.
func CompCharacters(cx *core.Scope, count int) string { return For(cx).CompCharacters(count) }

// CompCharacters says "{count, plural, one {# character} other {# characters}}"
// in the language of msgs.
func (msgs Messages) CompCharacters(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].CompCharacters; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" character")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" characters")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " حرف"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 个字符"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 個字元"
		}
	}
}

