// GestDown says "{count, number} down"
// in the language the app shows under cx.
func GestDown(cx *core.Scope, count int) string { return For(cx).GestDown(count) }

// GestDown says "{count, number} down"
// in the language of msgs.
func (msgs Messages) GestDown(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].GestDown; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return i18n.FormatNumber("en", float64(count)) + " down"
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " مضغوط"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 个按下"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 個按下"
		}
	}
}

// GestTouchLine says "{at} · page {page} · {count, number} down"
// in the language the app shows under cx.
func GestTouchLine(cx *core.Scope, at string, page string, count int) string {
	return For(cx).GestTouchLine(at, page, count)
}

// GestTouchLine says "{at} · page {page} · {count, number} down"
// in the language of msgs.
func (msgs Messages) GestTouchLine(at string, page string, count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].GestTouchLine; f != nil {
			return f(at, page, count)
		}
		switch lang {
		case "", "en":
			return at + " · page " + page + " · " + i18n.FormatNumber("en", float64(count)) + " down"
		case "ar":
			return at + " · الصفحة " + page + " · " + i18n.FormatNumber("ar", float64(count)) + " مضغوط"
		case "zh-Hans":
			return at + " · 页面 " + page + " · " + i18n.FormatNumber("zh-Hans", float64(count)) + " 个按下"
		case "zh-Hant":
			return at + " · 頁面 " + page + " · " + i18n.FormatNumber("zh-Hant", float64(count)) + " 個按下"
		}
	}
}

// GestTaps says "{count, plural, one {# tap} other {# taps}}"
// in the language the app shows under cx.
func GestTaps(cx *core.Scope, count int) string { return For(cx).GestTaps(count) }

// GestTaps says "{count, plural, one {# tap} other {# taps}}"
// in the language of msgs.
func (msgs Messages) GestTaps(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].GestTaps; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" tap")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" taps")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " ضغطة"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 次轻点"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 次輕點"
		}
	}
}

// GestPointerAt says "Pointer at {at}"
