// StocksShares says "{count, plural, one {# share} other {# shares}}"
// in the language the app shows under cx.
func StocksShares(cx *core.Scope, count int) string { return For(cx).StocksShares(count) }

// StocksShares says "{count, plural, one {# share} other {# shares}}"
// in the language of msgs.
func (msgs Messages) StocksShares(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].StocksShares; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" share")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" shares")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " سهم"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 股"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 股"
		}
	}
}

