// DockEdits says "{panel}: {count, plural, one {# edit} other {# edits}}"
// in the language the app shows under cx.
func DockEdits(cx *core.Scope, panel string, count int) string {
	return For(cx).DockEdits(panel, count)
}

// DockEdits says "{panel}: {count, plural, one {# edit} other {# edits}}"
// in the language of msgs.
func (msgs Messages) DockEdits(panel string, count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].DockEdits; f != nil {
			return f(panel, count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString(panel)
			b.WriteString(": ")
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" edit")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" edits")
			}
			return b.String()
		case "ar":
			return panel + ": " + i18n.FormatNumber("ar", float64(count)) + " تعديل"
		case "zh-Hans":
			return panel + "：" + i18n.FormatNumber("zh-Hans", float64(count)) + " 次编辑"
		case "zh-Hant":
			return panel + "：" + i18n.FormatNumber("zh-Hant", float64(count)) + " 次編輯"
		}
	}
}

