// ScrollPosts says "{count, plural, one {# post} other {# posts}}"
// in the language the app shows under cx.
func ScrollPosts(cx *core.Scope, count int) string { return For(cx).ScrollPosts(count) }

// ScrollPosts says "{count, plural, one {# post} other {# posts}}"
// in the language of msgs.
func (msgs Messages) ScrollPosts(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ScrollPosts; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" post")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" posts")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " منشور"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 篇帖子"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 篇貼文"
		}
	}
}

