// ShaderStartPressed says "Start pressed {count, plural, one {# time} other {# times}}"
// in the language the app shows under cx.
func ShaderStartPressed(cx *core.Scope, count int) string { return For(cx).ShaderStartPressed(count) }

// ShaderStartPressed says "Start pressed {count, plural, one {# time} other {# times}}"
// in the language of msgs.
func (msgs Messages) ShaderStartPressed(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ShaderStartPressed; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString("Start pressed ")
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" time")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" times")
			}
			return b.String()
		case "ar":
			return "ضُغط ابدأ " + i18n.FormatNumber("ar", float64(count)) + " مرة"
		case "zh-Hans":
			return "“开始”按了 " + i18n.FormatNumber("zh-Hans", float64(count)) + " 次"
		case "zh-Hant":
			return "「開始」按了 " + i18n.FormatNumber("zh-Hant", float64(count)) + " 次"
		}
	}
}

