// DiffLines says "{count, plural, one {# line} other {# lines}}"
// in the language the app shows under cx.
func DiffLines(cx *core.Scope, count int) string { return For(cx).DiffLines(count) }

// DiffLines says "{count, plural, one {# line} other {# lines}}"
// in the language of msgs.
func (msgs Messages) DiffLines(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].DiffLines; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" line")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" lines")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " سطر"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 行"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 行"
		}
	}
}

