// EditorErrors says "{count, plural, one {# error} other {# errors}}"
// in the language the app shows under cx.
func EditorErrors(cx *core.Scope, count int) string { return For(cx).EditorErrors(count) }

// EditorErrors says "{count, plural, one {# error} other {# errors}}"
// in the language of msgs.
func (msgs Messages) EditorErrors(count int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].EditorErrors; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" error")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(count)))
				b.WriteString(" errors")
			}
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(count)) + " أخطاء"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 个错误"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(count)) + " 個錯誤"
		}
	}
}

