// StorageKeysChars says "{keys, plural, one {# key} other {# keys}} · {chars, number} chars of 5 MB"
// in the language the app shows under cx.
func StorageKeysChars(cx *core.Scope, keys int, chars int) string {
	return For(cx).StorageKeysChars(keys, chars)
}

// StorageKeysChars says "{keys, plural, one {# key} other {# keys}} · {chars, number} chars of 5 MB"
// in the language of msgs.
func (msgs Messages) StorageKeysChars(keys int, chars int) string {
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].StorageKeysChars; f != nil {
			return f(keys, chars)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(keys)) {
			case i18n.One:
				b.WriteString(i18n.FormatNumber("en", float64(keys)))
				b.WriteString(" key")
			default:
				b.WriteString(i18n.FormatNumber("en", float64(keys)))
				b.WriteString(" keys")
			}
			b.WriteString(" · ")
			b.WriteString(i18n.FormatNumber("en", float64(chars)))
			b.WriteString(" chars of 5 MB")
			return b.String()
		case "ar":
			return i18n.FormatNumber("ar", float64(keys)) + " مفاتيح · " + i18n.FormatNumber("ar", float64(chars)) + " حرفًا من 5 ميغابايت"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(keys)) + " 个键 · 已用 " + i18n.FormatNumber("zh-Hans", float64(chars)) + " 个字符，共 5 MB"
		case "zh-Hant":
			return i18n.FormatNumber("zh-Hant", float64(keys)) + " 個鍵 · 已用 " + i18n.FormatNumber("zh-Hant", float64(chars)) + " 個字元，共 5 MB"
		}
	}
}

